import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {origins,targetNames,canDifferentiate,lineageTasks,lineageComplete,useTasks,useComplete} from './stem-models.js?v=20261023-physicscomplete01';
const cell=(x,y,label,kind='stem')=>{
 const plant=['plant','root','xylem','leaf'].includes(kind),extra=kind==='nerve'?'<path d="M26 0H78M78 0L94-14M78 0L94 14M-26 0L-45-18M-26 0L-45 18" fill="none" stroke="#ed8b78" stroke-width="5"/>':kind==='muscle'?'<path d="M-20-12V12M-10-15V15M0-15V15M10-15V15M20-12V12" stroke="#182e44" stroke-width="2"/>':kind==='root'?'<path d="M27-7H62Q75 0 62 7H27" stroke="#f8f6f2" stroke-width="2" fill="#ed8b78"/>':kind==='xylem'?'<path d="M-16-24V24M16-24V24M-29-12H-16M16 0H29M-29 12H-16" stroke="#182e44" stroke-width="4"/>':kind==='leaf'?'<ellipse cx="-16" cy="-12" rx="6" ry="4" fill="#182e44"/><ellipse cx="17" cy="12" rx="6" ry="4" fill="#182e44"/>':'';
 return `<g transform="translate(${x} ${y})"><${plant?'rect x="-29" y="-24" width="58" height="48" rx="9"':'ellipse cx="0" cy="0" rx="29" ry="24"'} fill="${kind==='stem'?'#d4dfe7':'#ed8b78'}" stroke="#f8f6f2" stroke-width="2"/>${extra}${kind==='xylem'?'':kind==='blood'?'<ellipse rx="13" ry="8" fill="#f8f6f2" opacity=".6"/>':'<circle r="9" fill="#182e44"/>'}<text y="43" fill="#f8f6f2" text-anchor="middle" font-size="12">${label}</text></g>`;
};
const arrow=(x1,y1,x2,y2)=>`<path d="M${x1} ${y1} L${x2} ${y2}" stroke="#b7c8d6" stroke-width="2" fill="none" marker-end="url(#stemArrow)"/>`;
const wrap=body=>`<svg class="shell-diagram" viewBox="0 0 480 340" role="img" aria-label="Labelled stem-cell pathway"><defs><marker id="stemArrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="none" stroke="#b7c8d6"/></marker></defs>${body}</svg>`;
export function showStem(origin='embryo',w={}){const o=origins[origin]||origins.embryo,target=w.target||o.targets[0],renewed=w.renewed?.[origin],attempted=w.explored?.includes(origin+':'+target),allowed=canDifferentiate(origin,target);renderDiagram(o.name,o.scope,wrap(cell(240,55,'Stem cell')+(renewed?arrow(215,80,135,135)+cell(120,165,'Stem cell')+arrow(260,80,335,135)+cell(350,165,'Stem cell'):'<text x="240" y="155" text-anchor="middle" fill="#d4dfe7">Predict, then self-renew</text>')+(attempted?arrow(350,195,350,250)+(allowed?cell(350,280,targetNames[target],target):'<text x="350" y="275" text-anchor="middle" fill="#f8f6f2">Not a supported pathway</text>'):''))+'<p class="diagram-caption">A lineage diagram, not a time-lapse. Only selected outcomes are shown; embryo cells can form most human cell types. Shapes, numbers and timing are symbolic; the blood example is a red blood cell.</p>','SELF-RENEWAL & DIFFERENTIATION');}
export function showStemUse(context='therapy',w={}){const choice=w.useChoice||({therapy:'insulin',cloning:'unrelated',plants:'rare'}[context]),matched=choice==='matched',virus=w.risk==='virus';let body;if(context==='therapy'){body=cell(100,90,'Stem cells')+arrow(140,90,310,90)+cell(355,90,choice==='nerve'?'Nerve cell':'Insulin-producing cell',choice==='nerve'?'nerve':'special')+`<text x="240" y="210" fill="#f8f6f2" text-anchor="middle" font-size="18">${choice==='nerve'?'Paralysis':'Diabetes'}: potential cell replacement</text><text x="240" y="245" fill="#d4dfe7" text-anchor="middle">Relevant function ≠ proven cure</text>`;}else if(context==='cloning'){body=cell(95,90,'Patient')+cell(345,90,matched?'Matched embryo':'Unrelated source')+`<path d="M125 90H310" stroke="${matched?'#ed8b78':'#b7c8d6'}" stroke-width="3" stroke-dasharray="${matched?'0':'8 6'}"/><text x="240" y="190" text-anchor="middle" fill="#f8f6f2">${matched?'Same genes: matching addresses rejection':'Different genes: rejection is a concern'}</text><text x="240" y="235" text-anchor="middle" fill="#f8f6f2">${virus?'Virus present: infection risk remains':'No virus shown in this model'}</text><text x="240" y="280" text-anchor="middle" fill="#d4dfe7">Genetic match and contamination are different questions</text>`;}else{body=cell(85,90,'Meristem','plant')+arrow(125,90,220,90)+cell(265,90,'Clone','plant')+cell(375,90,'Clone','plant')+`<text x="240" y="210" text-anchor="middle" fill="#f8f6f2">${choice==='crop'?'Multiply a selected resistant crop':'Conserve a rare plant species'}</text><text x="240" y="250" text-anchor="middle" fill="#d4dfe7">Quick, economical copies · shared genetic traits</text>`;}renderDiagram(context==='cloning'?'Therapeutic cloning':context==='plants'?'Plant cloning':'Potential treatment',context==='cloning'?'Genetic match does not remove every risk':'Compare purpose and evidence',wrap(body)+'<p class="diagram-caption">Conceptual pathways only. No laboratory technique, treatment success rate or clinical guarantee is represented.</p>','WEIGH THE BENEFITS & RISKS');}
const options=(list,value)=>'<option value="">Choose…</option>'+list.map(([v,label])=>`<option value="${v}"${value===v?' selected':''}>${label}</option>`).join('');
export function mountStem(l,p,root,{save,done,feedback}){const w=p.widget,$=s=>root.querySelector(s);w.task??=0;w.passed??=[];const lineage=l.widget==='stem-lineage',tasks=lineage?lineageTasks:useTasks,t=tasks[w.task%3],id=lineage?t.origin:t.id;const finish=()=>{if(!w.passed.includes(id))w.passed.push(id);p.widgetDone=w.passed.length===3;save();if(p.widgetDone)done();$('#stemProgress').textContent=w.passed.length+' / 3 complete';};const tail='<button class="secondary" id="checkStem">Check reasoning</button><button class="secondary" id="nextStem">Next challenge →</button><p id="stemProgress">'+w.passed.length+' / 3 complete</p>';
if(lineage){w.predictions??={};w.renewed??={};w.explored??=[];w.targets??={};w.target=w.targets[id]||t.target;root.innerHTML=`<p><b>${w.task+1} / 3 · ${origins[id].name}</b></p><p>${t.prompt}</p><label class="field-label" for="stemPrediction">Predict the source’s capacity</label><select id="stemPrediction" class="lab-select">${options(t.options,w.predictions[id])}</select><button class="secondary" id="renewStem">Self-renew: make more stem cells</button><label class="field-label" for="stemTarget">Choose a specialised outcome</label><select class="lab-select" id="stemTarget">${options((id==='meristem'?['root','xylem','leaf']:['nerve','muscle','blood']).map(v=>[v,targetNames[v]]),w.target)}</select><button class="secondary" id="differentiateStem">Test differentiation</button><p id="stemOutcome" aria-live="polite"></p>`+tail;
$('#stemPrediction').onchange=e=>{w.predictions[id]=e.target.value;save();};$('#renewStem').onclick=()=>{if(!w.predictions[id]){feedback('Make a prediction before changing the model.',true);return;}w.renewed[id]=true;save();showStem(id,w);};$('#stemTarget').onchange=e=>{w.target=e.target.value;w.targets[id]=w.target;save();showStem(id,w);};$('#differentiateStem').onclick=()=>{if(!w.renewed[id]||!w.target){feedback('Predict and self-renew first, then choose an outcome.',true);return;}const key=id+':'+w.target;if(!w.explored.includes(key))w.explored.push(key);save();showStem(id,w);$('#stemOutcome').textContent=canDifferentiate(id,w.target)?'A supported example: '+targetNames[w.target]+'.':'Not supported by the adult bone-marrow pathways in this model. Compare blood cells.';};$('#checkStem').onclick=()=>{if(!lineageComplete(w,t)){feedback('Self-renew, test '+targetNames[t.target]+' and '+targetNames[id==='marrow'?'blood':id==='embryo'?'muscle':'xylem']+', then check your capacity prediction. More stem cells and specialised cells are different outcomes.',true);return;}feedback(origins[id].scope+'. Self-renewal maintains stem cells; differentiation produces a specialised role.');finish();};showStem(id,w);
}else{w.seenUses??=[];w.useAnswers??={};w.useChoices??={};w.risksSeen??=[];w.useChoice=w.useChoices[id]||t.choices[0][0];root.innerHTML=`<p><b>${w.task+1} / 3 · ${t.title}</b></p><p>${t.prompt}</p><label class="field-label" for="stemUseChoice">Compare the proposals</label><select class="lab-select" id="stemUseChoice">${options(t.choices,w.useChoice)}</select><button class="secondary" id="runStemUse">Explore this proposal</button>${id==='cloning'?'<label class="field-label" for="stemRisk">Contamination in the model</label><select id="stemRisk" class="lab-select">'+options([['clean','No virus shown'],['virus','Viral contamination']],w.risk||'clean')+'</select>':''}<label class="field-label" for="stemUseAnswer">Evaluate what the model establishes</label><select class="lab-select" id="stemUseAnswer">${options(t.options,w.useAnswers[id])}</select>`+tail;
$('#stemUseChoice').onchange=e=>{w.useChoice=e.target.value;w.useChoices[id]=w.useChoice;save();showStemUse(id,w);};$('#runStemUse').onclick=()=>{if(!w.useChoice)return;const key=id+':'+w.useChoice;if(!w.seenUses.includes(key))w.seenUses.push(key);if(id==='cloning'&&!w.risksSeen.includes(w.risk||'clean'))w.risksSeen.push(w.risk||'clean');save();showStemUse(id,w);feedback('Proposal explored. Compare the other proposal before evaluating.');};if($('#stemRisk'))$('#stemRisk').onchange=e=>{w.risk=e.target.value;save();showStemUse(id,w);};$('#stemUseAnswer').onchange=e=>{w.useAnswers[id]=e.target.value;save();};$('#checkStem').onclick=()=>{if(!useComplete(w,t)){feedback('Explore both proposals'+(id==='cloning'?' and both contamination states':'')+', then distinguish potential benefits from guarantees.'+(id==='cloning'?' A genetic match does not remove viral risk.':''),true);return;}feedback(id==='plants'?'Cloning can conserve and multiply selected plants, while copies share genetic vulnerabilities.':'A useful proposal requires evidence about benefits and risks. Ethical and religious objections also deserve consideration.');finish();};showStemUse(id,w);}
$('#nextStem').onclick=()=>{if(!w.passed.includes(id)){feedback('Complete this challenge first.',true);return;}w.task=(w.task+1)%3;save();feedback('');mountStem(l,p,root,{save,done,feedback});};}
